-- Esquema: columna oculto + descripcion unica en proveedores, id como identity, policies de escritura admin.
-- Ya aplicado directo via el conector MCP de Supabase el 2026-08-17; este archivo documenta el cambio.

alter table public.proveedores add column oculto boolean not null default false;
alter table public.proveedores add constraint proveedores_descripcion_key unique (descripcion);

create policy escritura_admin_insert on public.proveedores for insert to authenticated with check (auth.uid() in (select id from public.admins));
create policy escritura_admin_update on public.proveedores for update to authenticated using (auth.uid() in (select id from public.admins));
create policy escritura_admin_delete on public.proveedores for delete to authenticated using (auth.uid() in (select id from public.admins));

-- Carga inicial de los 32 proveedores reales (antes solo existia id=0 'Sin Proveedor').
-- Nombres extraidos de la columna 'codprov' del excel de precios (exInput.xls), que es 1:1
-- contra los 4125 codigos de articulos ya en la base (verificado antes de aplicar).
-- Expoyer y Altamira quedan marcados oculto=true a pedido del cliente: sus articulos no
-- se muestran en el catalogo publico (ver filtro en app/page.tsx) aunque sigan en la base.
INSERT INTO proveedores (id, descripcion, oculto) VALUES (1, 'ALTAMIRA', true), (2, 'ARGENLAM', false), (3, 'AUTOCOR', false), (4, 'AVANT', false), (5, 'DAILY', false), (6, 'DENSO', false), (7, 'DISTRIMA', false), (8, 'DM', false), (9, 'ETMAN', false), (10, 'EXINTRAD', false), (11, 'EXPOYER', true), (12, 'FENIX', false), (13, 'FORCOR', false), (14, 'GKG', false), (15, 'GOICOECH', false), (16, 'JAVIERAL', false), (17, 'JAVIERCA', false), (18, 'JL', false), (19, 'LUX', false), (20, 'MONTESAN', false), (21, 'MOTCOR', false), (22, 'PUNTATO', false), (23, 'RAMONDA', false), (24, 'RAUMAN', false), (25, 'RD', false), (26, 'REYDI', false), (27, 'SZLOMOWI', false), (28, 'TOMMASI', false), (29, 'TRINTERL', false), (30, 'TURIN', false), (31, 'VERO', false), (32, 'VOVCHUK', false);

alter table public.proveedores alter column id add generated by default as identity;
select setval(pg_get_serial_sequence('public.proveedores','id'), (select max(id) from public.proveedores));

